define(["jquery"],function($){const PageEditor={editorSelectors:["#fitem_id_page_editor","#fitem_id_page","#fitem_id_content_editor","#fitem_id_content"],textareaSelectors:["textarea[name='page[text]']","textarea[name='content[text]']"],init:function(config){config=config||{};let $form=$('form[action="modedit.php"]').first();if(!$form.length){$form=$('form[action*="modedit.php"]').first()}if(!$form.length){return}PageEditor.addHiddenField($form,config.requestfield,config.linked?1:0);PageEditor.renderSuggestion($form,config);if(config.linked){PageEditor.lockMoodleEditor(M.util.get_string("pageeditor_linked","theme_degrade"));PageEditor.ensurePlaceholderContent()}},renderSuggestion:function($form,config){const body=config.linked?M.util.get_string("pageeditor_linked","theme_degrade"):M.util.get_string("pageeditor_suggestion","theme_degrade");const buttontext=config.linked&&config.editorurl?`<a class="btn btn-primary" href="${config.editorurl}">${M.util.get_string("pageeditor_open","theme_degrade")}</a>`:`<button type="button" class="btn btn-primary" id="theme-degrade-use-pageeditor">${M.util.get_string("pageeditor_use","theme_degrade")}</button>`;const $box=$(`
                <div class="alert alert-info theme-degrade-pageeditor-box" role="region" aria-label="${M.util.get_string("pageeditor_title","theme_degrade")}">
                    <div class="d-flex flex-column flex-md-row align-items-md-center justify-content-between gap-3">
                        <div>
                            <strong>${M.util.get_string("pageeditor_title","theme_degrade")}</strong>
                            <div class="small mt-1 theme-degrade-pageeditor-text">${body}</div>
                        </div>
                        <div class="flex-shrink-0 theme-degrade-pageeditor-actions">${buttontext}</div>
                    </div>
                </div>`);PageEditor.insertBeforeMoodleEditor($form,$box);$box.on("click","#theme-degrade-use-pageeditor",function(){PageEditor.addHiddenField($form,config.requestfield,1);PageEditor.ensurePlaceholderContent();PageEditor.lockMoodleEditor(M.util.get_string("pageeditor_save_to_open","theme_degrade"));$box.removeClass("alert-info").addClass("alert-success");$box.find(".theme-degrade-pageeditor-text").text(M.util.get_string("pageeditor_save_to_open","theme_degrade"));$(this).prop("disabled",true).text(M.util.get_string("pageeditor_selected","theme_degrade"))})},insertBeforeMoodleEditor:function($form,$box){const $editor=PageEditor.getEditorContainer();if($editor.length){$editor.first().before($box);return}const $contentSection=PageEditor.getContentSection();if($contentSection.length){const $collapseInner=$contentSection.find(".fcontainer, .collapsible-actions").first();if($collapseInner.length){$collapseInner.after($box)}else{$contentSection.prepend($box)}return}const $general=$("#id_general, fieldset#id_general").first();if($general.length){$general.append($box)}else{$form.prepend($box)}},getContentSection:function(){const sectionSelectors=["#id_contentsection","fieldset#id_contentsection","#id_contenthdr","fieldset#id_contenthdr"];for(let i=0;i<sectionSelectors.length;i++){const $section=$(sectionSelectors[i]).first();if($section.length){return $section}}const $editor=PageEditor.getEditorContainer();if($editor.length){const $fieldset=$editor.first().closest("fieldset");if($fieldset.length){return $fieldset}}return $()},getEditorContainer:function(){for(let i=0;i<PageEditor.editorSelectors.length;i++){const $element=$(PageEditor.editorSelectors[i]).first();if($element.length){return $element}}for(let i=0;i<PageEditor.textareaSelectors.length;i++){const $textarea=$(PageEditor.textareaSelectors[i]).first();if($textarea.length){const $wrapper=$textarea.closest(".fitem, .form-group, .mb-3");return $wrapper.length?$wrapper:$textarea}}return $()},addHiddenField:function($form,name,value){if(!name){return}let $field=$form.find(`input[name="${name}"]`);if(!$field.length){$field=$(`<input type="hidden" name="${name}">`).appendTo($form)}$field.val(value?"1":"0")},lockMoodleEditor:function(message){const text=message||M.util.get_string("pageeditor_save_to_open","theme_degrade");const $firstEditor=PageEditor.getEditorContainer();if($firstEditor.length){PageEditor.showSaveMessage($firstEditor.first(),text)}PageEditor.editorSelectors.forEach(function(selector){$(selector).each(function(){$(this).hide()})});PageEditor.textareaSelectors.forEach(function(selector){$(selector).each(function(){const $textarea=$(this);const $wrapper=$textarea.closest(".fitem, .form-group, .mb-3");if($wrapper.length){$wrapper.hide()}else{$textarea.hide()}})})},showSaveMessage:function($editor,text){let $message=$("#theme-degrade-pageeditor-save-message");if(!$message.length){$message=$(`
                    <div id="theme-degrade-pageeditor-save-message" class="alert alert-warning" role="status">
                        <strong>${M.util.get_string("pageeditor_title","theme_degrade")}</strong>
                        <div class="theme-degrade-pageeditor-save-message-text"></div>
                    </div>`);$editor.before($message)}$message.find(".theme-degrade-pageeditor-save-message-text").text(text);$message.show()},ensurePlaceholderContent:function(){const placeholder="<p>Content managed by the EAD Training visual editor.</p>";const $textareas=$("textarea[name='page[text]'], textarea[name='content[text]']");$textareas.each(function(){const textarea=this;if(!$(textarea).val().trim()){$(textarea).val(placeholder)}if(typeof tinyMCE!=="undefined"&&textarea.id&&tinyMCE.get(textarea.id)){const editor=tinyMCE.get(textarea.id);if(!editor.getContent().trim()){editor.setContent(placeholder)}}})}};return PageEditor});